#include <bits/stdc++.h>
using namespace std;

string toBinary(int x) {
    if (x == 0) return "0";
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 2)); // 记录当前最低位
        x /= 2;                         // 去掉当前最低位
    }
    reverse(s.begin(), s.end());        // 余数要倒序读
    return s;
}

int main() {
    int x;
    cin >> x;
    cout << toBinary(x) << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int x, k;
    cin >> x >> k; // k 从 0 开始，0 表示最低位

    if ((x & (1 << k)) != 0) {
        cout << "第 k 位是 1" << endl;
    } else {
        cout << "第 k 位是 0" << endl;
    }
    return 0;
}
